/**
 * server/utils/ca-cards.ts
 * ─────────────────────────────────────────────────────────────────────────────
 * Current-affairs cards for the Nitro API routes.
 *
 * The cards live in public/_ca/cards-runtime.json, generated by
 * scripts/generate-ca-export.ts during `predev` and `prebuild`.
 *
 * Do NOT reintroduce `queryCollection(event, ...)` here. Cloudflare Pages has no
 * runtime database, so a content query inside a server route throws and the
 * endpoint answers HTTP 500. Do NOT inline the multi-MB JSON into the worker
 * bundle either: reading static assets via Cloudflare ASSETS binding (edge) or
 * node:fs (Node/prerender/tests) keeps worker bundle size tiny and avoids
 * Rollup OOM during Nuxt/Nitro builds.
 */
import type { H3Event } from 'h3'
import { readFile } from 'node:fs/promises'
import { resolve } from 'node:path'

export interface CACard {
  id: string
  meta: Record<string, any>
}

let cachedCards: CACard[] | null = null
let loadingPromise: Promise<CACard[]> | null = null

export async function getCACards(event?: H3Event): Promise<CACard[]> {
  if (cachedCards) return cachedCards
  if (loadingPromise) return loadingPromise

  loadingPromise = (async () => {
    const assets = (event as any)?.context?.cloudflare?.env?.ASSETS
    if (assets && typeof assets.fetch === 'function') {
      const res = await assets.fetch(new URL('/_ca/cards-runtime.json', 'https://assets.local'))
      if (res.ok) {
        const parsed = (await res.json()) as CACard[]
        cachedCards = parsed
        return parsed
      }
    }

    const candidates = [
      resolve(process.cwd(), 'public/_ca/cards-runtime.json'),
      resolve(process.cwd(), '.output/public/_ca/cards-runtime.json'),
      resolve(process.cwd(), '../public/_ca/cards-runtime.json'),
      resolve(process.cwd(), 'dist/_ca/cards-runtime.json'),
      resolve(process.cwd(), 'content/data/ca/cards.json'),
    ]
    for (const filePath of candidates) {
      try {
        const raw = await readFile(filePath, 'utf-8')
        const parsed = JSON.parse(raw) as CACard[]
        cachedCards = parsed
        return parsed
      } catch {
        // Try next candidate path
      }
    }

    throw new Error('Unable to load current affairs dataset (_ca/cards-runtime.json)')
  })()

  try {
    return await loadingPromise
  } finally {
    loadingPromise = null
  }
}

/** Real date the news happened, with fallbacks used across the CA UI. */
export function entryDate(e: CACard): string {
  return e?.meta?.event_date || e?.meta?.date || e?.meta?.published_at || ''
}

export function entryTime(e: CACard): number {
  const t = new Date(entryDate(e)).getTime()
  return Number.isNaN(t) ? 0 : t
}

/** "Today" means this calendar day in IST (UTC+5:30). */
export function istStartOfToday(now: Date): Date {
  const istOffset = 5.5 * 60 * 60 * 1000
  const istNow = new Date(now.getTime() + istOffset)
  return new Date(Date.UTC(
    istNow.getUTCFullYear(),
    istNow.getUTCMonth(),
    istNow.getUTCDate(),
  ) - istOffset)
}

export type CAMode = 'high-yield' | 'all'

export function parseCAMode(raw: unknown): CAMode {
  return String(raw ?? 'all').trim().toLowerCase() === 'high-yield' ? 'high-yield' : 'all'
}

const CATEGORY_PYQ_WEIGHT: Record<string, number> = {
  telangana: 5,
  appointments: 4,
  awards: 4,
  defence: 4,
  science: 3,
  sports: 3,
  international: 3,
  economy: 3,
  judiciary: 3,
  environment: 2,
  books: 2,
  schemes: 1,
}

/**
 * Deterministic exam-priority score for a current-affairs card.
 * Higher scores surface Telangana-focus, factual difficulty, high-PYQ categories,
 * linked study topics, and richer MCQ coverage.
 */
export function highYieldScore(card: CACard): number {
  const meta = card?.meta ?? {}
  let score = 0

  const diff = String(meta.difficulty ?? '').trim().toUpperCase()
  if (diff === 'F') score += 4
  else if (diff === 'M') score += 2

  if (meta.is_telangana_focus === true) score += 5

  const cat = String(meta.category ?? '').trim().toLowerCase()
  score += CATEGORY_PYQ_WEIGHT[cat] ?? 0

  if (Array.isArray(meta.related_topic_ids) && meta.related_topic_ids.length > 0) score += 1
  if (Array.isArray(meta.mcqs) && meta.mcqs.length >= 2) score += 1

  return score
}

function compareHighYield(a: CACard, b: CACard): number {
  const scoreDiff = highYieldScore(b) - highYieldScore(a)
  if (scoreDiff !== 0) return scoreDiff
  const idA = String(a?.id ?? '')
  const idB = String(b?.id ?? '')
  return idA < idB ? -1 : idA > idB ? 1 : 0
}

function isHighPriorityCard(card: CACard): boolean {
  const meta = card?.meta ?? {}
  return meta.is_telangana_focus === true || String(meta.difficulty ?? '').trim().toUpperCase() === 'F'
}

/**
 * Select the daily High-Yield subset (typically 5-7 cards/day, up to 8 when a
 * day has >7 Telangana-focus or difficulty-'F' cards). Does not mutate `cards`.
 */
export function selectHighYieldCards(cards: readonly CACard[]): CACard[] {
  const byDay = new Map<string, CACard[]>()

  for (const card of cards) {
    const key = entryDate(card)
    let bucket = byDay.get(key)
    if (!bucket) {
      bucket = []
      byDay.set(key, bucket)
    }
    bucket.push(card)
  }

  const dayKeys = Array.from(byDay.keys()).sort((a, b) => (a > b ? -1 : a < b ? 1 : 0))
  const selected: CACard[] = []

  for (const key of dayKeys) {
    const dayCards = byDay.get(key)!
    const sorted = [...dayCards].sort(compareHighYield)
    const priorityCount = dayCards.filter(isHighPriorityCard).length
    const cap = priorityCount > 7 ? 8 : 7
    const qualified = sorted.filter(c => highYieldScore(c) >= 5)

    if (qualified.length >= 5) {
      selected.push(...qualified.slice(0, cap))
    } else {
      selected.push(...sorted.slice(0, Math.min(5, sorted.length)))
    }
  }

  return selected
}

export function windowCutoff(window: string, now: Date): Date | null {
  switch (window) {
    case '1D':
      return istStartOfToday(now)
    case '7D':
      return new Date(now.getTime() - 7 * 86400000)
    case '1M':
      return new Date(now.getTime() - 30 * 86400000)
    case '6M':
      return new Date(now.getTime() - 180 * 86400000)
    case '1Y':
      return new Date(now.getTime() - 365 * 86400000)
    default:
      return null // ALL or unrecognized
  }
}
